    "Ratios": {
      "SU2/U1": "sqrt(rho_wind*(A/T)**(2/3))/sqrt(rho_link*(A/T)**(2/3))",
      "SU3/SU2": "sqrt(rho_link*(A/T)**(2/3))/sqrt(rho_triplet*(A/T)**(2/3))"
