    "Lagrangian": "F_SU2**2/(4*g_SU2**2) + F_SU3**2/(4*g_SU3**2) + F_U1**2/(4*g_U1**2) + Lambda + R/(2*kappa)",
    "Status": "Pass"
  },
  "O7": {
    "Theta4": "acos((u0*v0 + u1*v1 + u2*v2 + u3*v3)/(sqrt(u0**2 + u1**2 + u2**2 + u3**2)*sqrt(v0**2 + v1**2 + v2**2 + v3**2)))",
    "Status": "Pass"
  },
  "O8": {
    "meff": "m0/(L_link + L_wind + W_writhe)",
    "Status": "Pass"
  }
}

